package config

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

// ScanTechnique identifies an nmap TCP scan technique.
type ScanTechnique int

const (
	NotSupportTechnique ScanTechnique = iota
	TCPSYN
	TCPConnect
	TCPACK
	TCPWindow
	TCPMaimon
	TCPNull
	TCPFIN
	TCPXmas
)

func (s ScanTechnique) String() string {
	switch s {
	case TCPSYN:
		return "sS"
	case TCPConnect:
		return "sT"
	case TCPACK:
		return "sA"
	case TCPWindow:
		return "sW"
	case TCPMaimon:
		return "sM"
	case TCPNull:
		return "sN"
	case TCPFIN:
		return "sF"
	case TCPXmas:
		return "sX"
	default:
		return ""
	}
}

// PortScanConf configures a scanner running on the Vuls host.
type PortScanConf struct {
	ScannerBinPath       string   `toml:"scannerBinPath" json:"scannerBinPath,omitempty"`
	ScanTechniques       []string `toml:"scanTechniques" json:"scanTechniques,omitempty"`
	HasPrivileged        bool     `toml:"hasPrivileged" json:"hasPrivileged,omitempty"`
	SourcePort           string   `toml:"sourcePort" json:"sourcePort,omitempty"`
	IsUseExternalScanner bool     `toml:"-" json:"-"`
}

func (c PortScanConf) IsZero() bool {
	return c.ScannerBinPath == "" && len(c.ScanTechniques) == 0 && c.SourcePort == "" && !c.HasPrivileged
}

func (c *PortScanConf) GetScanTechniques() (scanTechniques []ScanTechnique) {
	for _, name := range c.ScanTechniques {
		found := NotSupportTechnique
		for technique := TCPSYN; technique <= TCPXmas; technique++ {
			if strings.EqualFold(name, technique.String()) {
				found = technique
				break
			}
		}
		scanTechniques = append(scanTechniques, found)
	}
	return
}

// Validate checks settings required for external scanning.
func (c PortScanConf) Validate() (errs []error) {
	if c.IsZero() {
		return nil
	}
	if c.ScannerBinPath == "" {
		errs = append(errs, fmt.Errorf("portscan scannerBinPath is required"))
	} else if info, err := os.Stat(c.ScannerBinPath); err != nil {
		errs = append(errs, fmt.Errorf("portscan scannerBinPath: %w", err))
	} else if info.IsDir() || info.Mode()&0111 == 0 {
		errs = append(errs, fmt.Errorf("portscan scannerBinPath is not executable: %s", c.ScannerBinPath))
	}
	techniques := (&c).GetScanTechniques()
	if len(techniques) > 1 {
		errs = append(errs, fmt.Errorf("portscan multiple scan techniques are not supported"))
	}
	for i, technique := range techniques {
		if technique == NotSupportTechnique {
			errs = append(errs, fmt.Errorf("portscan unsupported scan technique: %s", c.ScanTechniques[i]))
		}
		if !c.HasPrivileged && technique != TCPConnect && technique != NotSupportTechnique {
			errs = append(errs, fmt.Errorf("portscan %s requires hasPrivileged", c.ScanTechniques[i]))
		}
		if technique == TCPConnect && c.SourcePort != "" {
			errs = append(errs, fmt.Errorf("portscan sourcePort is incompatible with TCP connect scan"))
		}
	}
	if c.SourcePort != "" {
		port, err := strconv.Atoi(c.SourcePort)
		if err != nil || port < 1 || port > 65535 {
			errs = append(errs, fmt.Errorf("portscan sourcePort must be an integer from 1 to 65535: %s", c.SourcePort))
		}
	}
	if c.HasPrivileged && os.Geteuid() != 0 && c.ScannerBinPath != "" {
		output, err := exec.Command("getcap", c.ScannerBinPath).CombinedOutput()
		if err != nil {
			errs = append(errs, fmt.Errorf("portscan capability check failed: %w: %s", err, strings.TrimSpace(string(output))))
		} else if !strings.Contains(string(output), "cap_net_raw") {
			errs = append(errs, fmt.Errorf("portscan scannerBinPath lacks cap_net_raw capability or has malformed capability data: %s", strings.TrimSpace(string(output))))
		}
	}
	return
}
package scanner

import (
	"encoding/xml"
	"fmt"
	"net"
	osExec "os/exec"
	"sort"
	"strings"

	"github.com/future-architect/vuls/config"
)

func setScanTechniques(conf config.PortScanConf) ([]string, error) {
	options := []string{}
	for i, technique := range (&conf).GetScanTechniques() {
		if technique == config.NotSupportTechnique {
			return nil, fmt.Errorf("unsupported scan technique: %s", conf.ScanTechniques[i])
		}
		options = append(options, "-"+technique.String())
	}
	return options, nil
}

func formatNmapOptionsToString(options []string) string { return strings.Join(options, " ") }

type nmapScan struct {
	Hosts []struct {
		Addresses []struct {
			Addr string `xml:"addr,attr"`
			Type string `xml:"addrtype,attr"`
		} `xml:"address"`
		Ports []struct {
			Protocol string `xml:"protocol,attr"`
			ID       string `xml:"portid,attr"`
			State    struct {
				State string `xml:"state,attr"`
			} `xml:"state"`
		} `xml:"ports>port"`
	} `xml:"host"`
}

func (l *base) execExternalPortScan(scanDestIPPorts map[string][]string) ([]string, error) {
	conf := l.ServerInfo.PortScan
	if conf == nil {
		return nil, fmt.Errorf("portscan configuration is missing")
	}
	if errs := conf.Validate(); len(errs) > 0 {
		return nil, fmt.Errorf("invalid portscan configuration: %v", errs)
	}
	techniques, err := setScanTechniques(*conf)
	if err != nil {
		return nil, err
	}
	result := []string{}
	for ip, ports := range scanDestIPPorts {
		parsedIP := net.ParseIP(ip)
		if parsedIP == nil {
			return nil, fmt.Errorf("invalid scan destination IP: %s", ip)
		}
		if !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host) && parsedIP.IsLoopback() {
			continue
		}
		if len(ports) == 0 {
			continue
		}
		sortedPorts := append([]string(nil), ports...)
		sort.Strings(sortedPorts)
		args := []string{"-oX", "-", "-n", "-Pn"}
		args = append(args, techniques...)
		if conf.SourcePort != "" {
			args = append(args, "-g", conf.SourcePort)
		}
		args = append(args, "-p", strings.Join(sortedPorts, ","), ip)
		output, err := osExec.Command(conf.ScannerBinPath, args...).CombinedOutput()
		if err != nil {
			return nil, fmt.Errorf("nmap scan of %s failed: %w: %s", ip, err, strings.TrimSpace(string(output)))
		}
		var scan nmapScan
		if err := xml.Unmarshal(output, &scan); err != nil {
			return nil, fmt.Errorf("parse nmap XML for %s: %w", ip, err)
		}
		for _, host := range scan.Hosts {
			// Use the requested IP: nmap's output can contain additional address types.
			for _, port := range host.Ports {
				if port.Protocol == "tcp" && port.State.State == "open" {
					result = append(result, net.JoinHostPort(ip, port.ID))
				}
			}
		}
	}
	return result, nil
}

